#!/bin/bash
# land-cv-profile.sh — A career is a list, so store it as one.
#
# The Jobs hub gets a real professional record: one CvEntry table with a `kind`
# discriminator, a three-way merge so a second upload never overwrites your own
# corrections, confidence and source columns so a low-confidence reading renders
# as a question, three visibility settings that all default to private, and a
# two-column CV document that finally prints your skills.
#
# TWO PACKAGES. This patch touches together-city-chat (schema, migration,
# service, controller, AI) and together-city-react (components, api, styles,
# tests). The web half ships the moment you push. THE API HALF NEEDS A
# MIGRATION RUN AND A DEPLOY — see the note this script prints at the end.
#
# Run from the repo root:  bash land-cv-profile.sh
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-react ] && [ -d together-city-chat ] || {
  echo "!! Run this from the Together-Ai repo root (the folder holding both packages)."; exit 1; }

# ── PRECONDITION: the commit this one is written against ──────────────────
#
# The log is captured into a variable and matched with `case`, NOT piped into
# `grep -q`. Under `set -o pipefail` that pipe is a race: grep exits the instant
# it matches the first line, git log takes SIGPIPE writing the other 39, and
# pipefail reports the whole pipeline as failed — so the check says the commit
# is MISSING precisely when it is the one you are standing on. It passes most of
# the time, which is worse than never passing. Every earlier land-*.sh has this
# shape; they got away with it.
LOG="$(git log --oneline -40)"
MARK="A stage does not export its ink"
case "$LOG" in
  *"$MARK"*) ;;
  *) echo "!! This patch applies on top of \"$MARK\", which is not in the last 40 commits."
     echo "   Run land-stage-ink.sh first."; exit 1 ;;
esac
NEEDS="A career is a list, so store it as one"
case "$LOG" in
  *"$NEEDS"*) echo "== \"$NEEDS\" is already here. Nothing to do."; exit 0 ;;
esac
# UNTRACKED LANDING ARTIFACTS ARE NOT DIRTY WORK.
#
# This script is running from the repo root, so it would otherwise fail on
# itself -- and on every spent land-*.sh, push-*.sh and *.patch left behind by
# the ones before it. None of those are changes to the codebase; refusing to run
# because of them turns "your tree is dirty" into a false alarm, which trains
# you to ignore a check whose whole job is to catch the real thing.
#
# A MODIFIED tracked file still stops this cold, which is the case that matters.
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

# ── the patch, one line of base64 ─────────────────────────────────────────
# One line on purpose: macOS ships LibreSSL, whose `openssl base64 -d -A`
# silently produces an EMPTY file from wrapped input. The sha256 below is the
# only thing standing between a truncated download and a half-applied patch.
# Not `mktemp -t cvprofile`: BSD mktemp fills in the X's for you, GNU mktemp
# demands them. Spelling the template out works on both, which is what lets
# this script be rehearsed on Linux before it is run on the Mac.
PATCH="$(mktemp "${TMPDIR:-/tmp}/cvprofile.XXXXXX")"
trap 'rm -f "$PATCH"' EXIT
cat <<'B64EOF' | tr -d '\n' | openssl base64 -d -A > "$PATCH"

B64EOF

WANT="3079e28e85be69eef59bb20ca8e022c3bb17398940eaffc3c6e49afa18e15823"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
[ "$GOT" = "$WANT" ] || { echo "!! Patch is corrupt."; echo "   want $WANT"; echo "   got  $GOT"; exit 1; }
echo "== patch verified ($(wc -c < "$PATCH" | tr -d ' ') bytes)"

git apply --check -C1 "$PATCH" || { echo "!! Patch does not apply cleanly. Nothing written."; exit 1; }
echo "== applies cleanly"

git am --keep-cr -C1 < "$PATCH"
echo "== committed"

# ── gates ─────────────────────────────────────────────────────────────────
echo
echo "== together-city-chat"
cd together-city-chat
npx tsc --noEmit
npx jest src/jobs src/security
cd ..

echo
echo "== together-city-react"
cd together-city-react
npx tsc --noEmit
npx vitest run
npx eslint src || true
node scripts/lint-ceiling.mjs
node scripts/dead-export-audit.mjs
node scripts/motion-ceiling.mjs
node scripts/a11y-audit.mjs
node scripts/nav-audit.mjs
npx vite build
cd ..

echo
echo "==============================================================="
echo " Landed: $NEEDS"
echo
echo " The WEB half is done — push and Vercel takes it."
echo
echo " The API half is yours to run, in this order:"
echo "   1.  cd together-city-chat"
echo "   2.  npx prisma migrate deploy        # applies 20260808120000_professional_record"
echo "   3.  npx prisma generate              # regenerates the client"
echo "   4.  npx tsc --noEmit                 # should still be clean"
echo "   5.  deploy to Railway"
echo
echo " Step 3 matters. jobs.service.ts carries a hand-written block of types"
echo " at the top standing in for the client, because prisma generate could"
echo " not run where this was written. Once you have regenerated, those"
echo " declarations are redundant and can be deleted in one edit — they are"
echo " a cast, not an @ts-expect-error, so nothing breaks if you leave them."
echo
echo " The migration carries your existing education and links textareas into"
echo " CvEntry rows and leaves the old columns in place. It is additive: no"
echo " column is dropped and no data is deleted."
echo "==============================================================="
